TARGET_X, TARGET_Y = 30.0, 3.5


G1_X, G1_Y = 13.0, 2.0


G2_X, G2_Y = 23.0, 2.4


DRAIN_LO, DRAIN_HI = 14.5, 17.0


SLIP_LO, SLIP_HI = 17.5, 20.0


WIND_LO, WIND_HI = 20.5, 28.0


WIND_AMP = 20.0


WIND_OMEGA = 0.055


MAX_THRUST = 120.0


LOW_THRUST = 90.0


HEAT_SAFE_FRAC = 0.88


def _waypoint(x, y):
    if x < G1_X - 0.1:
        return (G1_X, G1_Y)
    if x < G2_X - 0.1:
        return (G2_X, G2_Y)
    return (TARGET_X, TARGET_Y)


